policies.inbound:

%{ if oauth ~}



%{ endif ~}





            application/json

          @{
            var body = new JObject();
            body["team"] = "${team}";
            body["credentialType"] = "${credential_label}";
            body["clientId"] = context.Variables.GetValueOrDefault("aipClientId", "");
            body["accessWindow"] = context.Variables.GetValueOrDefault("aipWindow", "");
            body["allowedDeployments"] = new JArray(${granted});
            return body.ToString();
          }



    <set-variable name="aipRequested" value="@{
      var fromPath = context.Request.MatchedParameters.GetValueOrDefault("deployment-id", "");
      if (!string.IsNullOrEmpty(fromPath)) { return fromPath; }
      if (context.Request.Body == null) { return ""; }
      var body = context.Request.Body.As(preserveContent: true);
      return body["model"] == null ? "" : body["model"].ToString();
    }" />
%{ if length(models) > 0 ~}

%{ for model in models ~}




%{ endfor ~}




            application/json

          {"code":"model-not-granted"}



%{ else ~}



        application/json

      {"code":"model-not-granted"}

%{ endif ~}
















        @{
          var body = context.Request.Body.As(preserveContent: true);
          body["model"] = (string)context.Variables["aipDeployment"];
          return body.ToString();
        }
